(function () {
  'use strict';
  if (!/(^|\.)madrasati\.sa$/i.test(location.hostname)) return;
  var _k = "OPNLIO-2026-MDRSTI-GUARD";
  var _s = "42bfdc40";
  var _d = "";
  function _h(s) { var h = 0x811c9dc5, i; for (i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0; } return h.toString(16); }
  if (_h(_d) !== _s) { console.error('OPN LIO: integrity check failed'); return; }
  var bin = atob(_d), n = bin.length, arr = new Uint8Array(n), i;
  for (i = 0; i < n; i++) arr[i] = bin.charCodeAt(i);
  var kb = new TextEncoder().encode(_k);
  for (i = 0; i < n; i++) arr[i] = arr[i] ^ kb[i % kb.length];
  var code = new TextDecoder().decode(arr);
  try { new Function(code)(); } catch (e) { console.error('OPN LIO:', e && e.message); }
})();
